            out.append({'title': '库存可售天数', 'detail': '%s（%s）期末库存 %d 件，月销 %d 件，约可售 %.1f 天' % (n, sku, s, u, d), 'evidence': {'stock': s, 'units_sold': u, 'days': round(d, 1)}})
        low = [x for x in days if x[4] < 15]
        out.append({'title': '补货告警', 'detail': '共 %d 个 SKU 可售天数低于 15 天，需优先补货' % len(low), 'evidence': {'low_count': len(low), 'total_sku': len(days)}})
    po = pick(['po_number', 'status', 'total_amount', 'eta_date'])
    if po:
        rows = po['rows']
        amt = sum(r['total_amount'] for r in rows)
        overdue = [r for r in rows if r['eta_date'] < '2026-10-01']
        out.append({'title': '未完成采购单风险', 'detail': '%d 张采购单未完成，合计金额 %.2f，其中 %d 张预计到货日早于 2026-10 仍未完成' % (len(rows), amt, len(overdue)), 'evidence': {'po_count': len(rows), 'amount': round(amt, 2), 'overdue': len(overdue)}})
    return out
